-- Isolated test baseline reflecting the inspected production columns and legacy
-- broad coordinator policies. Never apply this fixture to a project database.
create role anon;
create role authenticated;
create role service_role bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth to anon, authenticated, service_role;
grant execute on function auth.uid() to anon, authenticated, service_role;
create type public.application_status as enum ('Pending','Interview','Accepted','Rejected','Offer Declined');
create table public.users(id uuid primary key, role text not null, full_name text not null, student_id text, email text, phone_number text, avatar_url text, updated_at timestamptz);
create table public.semesters(id integer primary key generated by default as identity, name text not null, start_date date not null, end_date date not null, is_active boolean default false);
create table public.student_semesters(id integer primary key generated by default as identity,student_id uuid references public.users(id),semester_id integer references public.semesters(id));
create table public.checklist_templates(id integer primary key generated by default as identity, title text not null, description text, required boolean, display_order integer, semester_id integer references public.semesters(id));
create table public.student_checklists(id integer primary key generated by default as identity, student_id uuid references public.users(id),checklist_item_id integer references public.checklist_templates(id),is_completed boolean,completed_at timestamptz,due_date date,notes text,override_reason text,updated_by_admin uuid);
create table public.job_applications(id integer primary key generated by default as identity,student_id uuid references public.users(id),company_name text not null,position text,application_date date,status public.application_status,notes text,created_at timestamptz,updated_at timestamptz,override_reason text,updated_by_admin uuid);
create table public.weekly_logbook_tracking(id integer primary key generated by default as identity,student_id uuid references public.users(id),semester_id integer references public.semesters(id),week_number integer,is_submitted boolean,submitted_at timestamptz,reminder_sent boolean);
grant all on all tables in schema public to anon, authenticated, service_role;
grant all on all sequences in schema public to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;
do $$ declare t text; begin
  foreach t in array array['users','semesters','student_semesters','checklist_templates','student_checklists','job_applications','weekly_logbook_tracking'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('create policy legacy_broad on public.%I for all to authenticated using (true) with check (true)',t);
  end loop;
end $$;
